// Given: visual algorithms for the dot product, the cross product and projection (pill 0.4).
// Do not edit this file. Deliberately standalone: it does not use the Exercise 0 functions.
//
// Spoiler note: these compute dot and cross for the visuals. Read pill 0.4 first.
import type { Vec2 } from "../../math/vec2";
import { trace } from "../../trace/trace";

const O = { x: 0, y: 0 };
const EPS = 1e-9;
const len = (v: Vec2) => Math.hypot(v.x, v.y);
const degrees = (rad: number) => (rad * 180) / Math.PI;

/** Where b lands on the line through the origin along a: the "shadow" of b on a. */
function foot(a: Vec2, b: Vec2): Vec2 {
  const aa = a.x * a.x + a.y * a.y;
  if (aa < EPS) return O;
  const k = (a.x * b.x + a.y * b.y) / aa;
  return { x: k * a.x, y: k * a.y };
}

/** A long segment through the origin along a, to show "the line of a". */
function lineOf(a: Vec2): { a: Vec2; b: Vec2 } {
  const l = len(a);
  if (l < EPS) return { a: O, b: O };
  const u = { x: a.x / l, y: a.y / l };
  return { a: { x: -u.x * 20, y: -u.y * 20 }, b: { x: u.x * 20, y: u.y * 20 } };
}

/** Dot product: a.x*b.x + a.y*b.y = |a||b| cos(angle between). */
export function tracedDot(a: Vec2, b: Vec2): number {
  const dot = a.x * b.x + a.y * b.y;
  const la = len(a);
  const lb = len(b);
  const shadow = la < EPS ? 0 : dot / la; // signed length of b's shadow on a
  const f = foot(a, b);
  const cos = la < EPS || lb < EPS ? 0 : dot / (la * lb);
  const arrows = [
    { kind: "arrow", from: O, to: a, label: "a", color: "a" },
    { kind: "arrow", from: O, to: b, label: "b", color: "b" },
  ] as const;
  trace.begin("a · b");
  trace.step("Two vectors, a and b, from the same point", [...arrows], {
    "a.x": a.x,
    "a.y": a.y,
    "b.x": b.x,
    "b.y": b.y,
  });
  // Lines first, so the vectors are drawn on top of them.
  const guides = [
    { kind: "segment", a: lineOf(a).a, b: lineOf(a).b, color: "muted" },
    { kind: "segment", a: b, b: f, color: "muted" },
  ] as const;
  const shadowArrow = {
    kind: "arrow",
    from: O,
    to: f,
    label: "shadow of b",
    color: "highlight",
  } as const;
  trace.step(
    "Drop b straight onto the line of a: its shadow",
    [...guides, ...arrows, shadowArrow],
    {
      "shadow length": shadow,
    },
  );
  trace.step("a · b is |a| times the shadow length", [...guides, ...arrows, shadowArrow], {
    "a · b": dot,
    "|a|": la,
    "shadow length": shadow,
    "|a| × shadow": la * shadow,
    "cos(angle)": cos,
    "angle (degrees)":
      la < EPS || lb < EPS ? 0 : degrees(Math.acos(Math.max(-1, Math.min(1, cos)))),
  });
  trace.end();
  return dot;
}

/** 2D cross product: a.x*b.y - a.y*b.x = |a||b| sin(angle from a to b), the signed area. */
export function tracedCross(a: Vec2, b: Vec2): number {
  const cross = a.x * b.y - a.y * b.x;
  const la = len(a);
  const lb = len(b);
  const sin = la < EPS || lb < EPS ? 0 : cross / (la * lb);
  const sum = { x: a.x + b.x, y: a.y + b.y };
  const arrows = [
    { kind: "arrow", from: O, to: a, label: "a", color: "a" },
    { kind: "arrow", from: O, to: b, label: "b", color: "b" },
  ] as const;
  const verdict =
    Math.abs(cross) < 1e-6
      ? "cross = 0: a and b are parallel"
      : cross > 0
        ? "cross > 0: b is counter-clockwise from a"
        : "cross < 0: b is clockwise from a";
  trace.begin("cross(a, b)");
  trace.step("Two vectors, a and b, from the same point", [...arrows], {
    "a.x": a.x,
    "a.y": a.y,
    "b.x": b.x,
    "b.y": b.y,
  });
  trace.step(
    "They span a parallelogram",
    [{ kind: "polygon", pts: [O, a, sum, b], color: "highlight" }, ...arrows],
    { area: Math.abs(cross) },
  );
  trace.step(
    verdict,
    [
      { kind: "polygon", pts: [O, a, sum, b], color: "highlight" },
      ...arrows,
      {
        kind: "text",
        p: { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 },
        text: `cross = ${cross.toFixed(2)}`,
        color: "highlight",
      },
    ],
    { cross, area: Math.abs(cross), "sin(angle)": sin },
  );
  trace.end();
  return cross;
}

/** Splits b into the part along a and the part across it. Returns both signed lengths. */
export function tracedProjection(a: Vec2, b: Vec2): { along: number; across: number } {
  const la = len(a);
  const n = la < EPS ? O : { x: a.x / la, y: a.y / la }; // unit axis
  const along = n.x * b.x + n.y * b.y; // b . n
  const across = n.x * b.y - n.y * b.x; // cross(n, b): the signed distance from the axis
  const f = { x: n.x * along, y: n.y * along };
  trace.begin("project b onto the axis of a");
  trace.step(
    "The axis: a, scaled to length 1",
    [
      { kind: "segment", a: lineOf(a).a, b: lineOf(a).b, color: "muted" },
      { kind: "arrow", from: O, to: n, label: "n", color: "normal" },
      { kind: "arrow", from: O, to: b, label: "b", color: "b" },
    ],
    { "n.x": n.x, "n.y": n.y },
  );
  trace.step(
    "Along the axis: b · n is how far b reaches in the direction of n",
    [
      { kind: "segment", a: lineOf(a).a, b: lineOf(a).b, color: "muted" },
      { kind: "arrow", from: O, to: b, label: "b", color: "b" },
      { kind: "arrow", from: O, to: f, label: "along", color: "highlight" },
    ],
    { along: along },
  );
  trace.step(
    "Across the axis: what is left over, at a right angle",
    [
      { kind: "segment", a: lineOf(a).a, b: lineOf(a).b, color: "muted" },
      { kind: "arrow", from: O, to: f, label: "along", color: "highlight" },
      { kind: "arrow", from: f, to: b, label: "across", color: "contact" },
      { kind: "arrow", from: O, to: b, label: "b", color: "b" },
    ],
    {
      along,
      across,
      "along² + across²": along * along + across * across,
      "|b|²": b.x * b.x + b.y * b.y,
    },
  );
  trace.end();
  return { along, across };
}
